pub fn lookup_native_hover(word: &str, qualified: &str) -> Option<&'static str> {
    match qualified {
        "cli.parse" => Some("```conduit\nfunc cli.parse<T>() -> T | CliError\n```\nParses process CLI arguments into `T` (defined via `cli` DSL or `@cli.*` struct annotations)."),
        "cli.parse_args" => Some("```conduit\nfunc cli.parse_args<T>(args: [String]) -> T | CliError\n```\nParses an explicit `[String]` argument list into `T`."),
        "cli.help" => Some("```conduit\nfunc cli.help<T>() -> String\n```\nReturns the formatted `--help` text for CLI schema `T`."),
        "env.load" => Some("```conduit\nfunc env.load<T>() -> T | EnvError\n```\nLoads environment variables into struct `T` using `@env` field annotations and defaults."),
        "env.get" => Some("```conduit\nfunc env.get(name: String) -> String?\n```\nReturns the environment variable value, or `nil` if unset."),
        "env.require" => Some("```conduit\nfunc env.require(name: String) -> String | EnvError\n```\nReturns the environment variable value, or `EnvError` if unset or empty."),
        "env.args" => Some("```conduit\nfunc env.args() -> [String]\n```\nReturns the command-line arguments passed to the process."),
        "fs.read_text" => Some("```conduit\nfunc fs.read_text(path: String) -> String | FsError\n```\nReads the entire UTF-8 file into a string."),
        "fs.write_text" => Some("```conduit\nfunc fs.write_text(path: String, data: String) -> Void | FsError\n```\nWrites a string to a file, creating or truncating it."),
        "fs.append_text" => Some("```conduit\nfunc fs.append_text(path: String, data: String) -> Void | FsError\n```\nAppends a string to a file, creating it if needed."),
        "fs.write_atomic" => Some("```conduit\nfunc fs.write_atomic(path: String, data: String) -> Void | FsError\n```\nWrites to a temporary sibling file, flushes, and atomically renames over `path`."),
        "fs.read_lines" => Some("```conduit\nfunc fs.read_lines(path: String) -> [String] | FsError\n```\nReads all lines from a UTF-8 file."),
        "fs.each_line" => Some("```conduit\nfunc fs.each_line(path: String, cb: (String) -> Void) -> Int | FsError\n```\nStreams a file line-by-line (64 KB buffer) and invokes `cb` for each line, returning the line count."),
        "fs.open_read" => Some("```conduit\nfunc fs.open_read(path: String) -> Reader | FsError\n```\nOpens a buffered streaming `Reader` (64 KB buffer)."),
        "fs.open_write" => Some("```conduit\nfunc fs.open_write(path: String) -> Writer | FsError\n```\nOpens a buffered streaming `Writer` (64 KB buffer), creating or truncating the file."),
        "fs.open_append" => Some("```conduit\nfunc fs.open_append(path: String) -> Writer | FsError\n```\nOpens a buffered streaming `Writer` (64 KB buffer) in append mode."),
        "fs.exists" => Some("```conduit\nfunc fs.exists(path: String) -> Bool\n```\nReturns `true` if `path` exists."),
        "fs.is_file" => Some("```conduit\nfunc fs.is_file(path: String) -> Bool\n```\nReturns `true` if `path` is a regular file."),
        "fs.is_dir" => Some("```conduit\nfunc fs.is_dir(path: String) -> Bool\n```\nReturns `true` if `path` is a directory."),
        "fs.size" => Some("```conduit\nfunc fs.size(path: String) -> Int | FsError\n```\nReturns the file size in bytes."),
        "fs.list_dir" => Some("```conduit\nfunc fs.list_dir(path: String) -> [String] | FsError\n```\nReturns sorted entry names in directory `path`."),
        "fs.mkdir_all" => Some("```conduit\nfunc fs.mkdir_all(path: String) -> Void | FsError\n```\nRecursively creates directories."),
        "fs.remove" => Some("```conduit\nfunc fs.remove(path: String) -> Void | FsError\n```\nRemoves a file or directory (recursively for directories)."),
        "fs.copy" => Some("```conduit\nfunc fs.copy(src: String, dst: String) -> Void | FsError\n```\nCopies file `src` to `dst`."),
        "fs.rename" => Some("```conduit\nfunc fs.rename(src: String, dst: String) -> Void | FsError\n```\nRenames or moves `src` to `dst`."),
        "path.join" => Some("```conduit\nfunc path.join(a: String, b: String) -> String\n```\nJoins two path segments using the platform separator."),
        "path.join_all" => Some("```conduit\nfunc path.join_all(parts: [String]) -> String\n```\nJoins a list of path segments."),
        "path.dirname" => Some("```conduit\nfunc path.dirname(p: String) -> String\n```\nReturns the parent directory of `p`."),
        "path.basename" => Some("```conduit\nfunc path.basename(p: String) -> String\n```\nReturns the final file/directory name of `p`."),
        "path.ext" => Some("```conduit\nfunc path.ext(p: String) -> String\n```\nReturns the file extension without leading dot, or `\"\"`."),
        "path.stem" => Some("```conduit\nfunc path.stem(p: String) -> String\n```\nReturns the file name without extension."),
        "path.normalize" => Some("```conduit\nfunc path.normalize(p: String) -> String\n```\nLexically normalizes `.` and `..` segments."),
        "path.is_abs" => Some("```conduit\nfunc path.is_abs(p: String) -> Bool\n```\nReturns `true` if `p` is an absolute path."),
        "path.with_ext" => Some("```conduit\nfunc path.with_ext(p: String, ext: String) -> String\n```\nReplaces or adds the file extension on `p`."),
        "process.run" => Some("```conduit\nfunc process.run(cmd: String, args: [String]) -> Output | ProcessError\n```\nRuns an external command and captures `code`, `stdout`, and `stderr`."),
        "process.status" => Some("```conduit\nfunc process.status(cmd: String, args: [String]) -> Int | ProcessError\n```\nRuns an external command inheriting stdio and returns its exit code."),
        "process.cwd" => Some("```conduit\nfunc process.cwd() -> String | ProcessError\n```\nReturns the current working directory."),
        "process.set_cwd" => Some("```conduit\nfunc process.set_cwd(dir: String) -> Void | ProcessError\n```\nChanges the current working directory."),
        "process.pid" => Some("```conduit\nfunc process.pid() -> Int\n```\nReturns the current OS process ID."),
        "process.exit" => Some("```conduit\nfunc process.exit(code: Int) -> Void\n```\nTerminates the process with exit code `code`."),
        "crypto.sha256" => Some("```conduit\nfunc crypto.sha256(data: String) -> String\n```\nComputes the lowercase hex SHA-256 digest of `data`."),
        "crypto.hmac_sha256" => Some("```conduit\nfunc crypto.hmac_sha256(key: String, data: String) -> String\n```\nComputes the lowercase hex HMAC-SHA256 tag."),
        "crypto.base64_encode" => Some("```conduit\nfunc crypto.base64_encode(data: String) -> String\n```\nEncodes UTF-8 string `data` as standard Base64."),
        "crypto.base64_decode" => Some("```conduit\nfunc crypto.base64_decode(b64: String) -> String | CryptoError\n```\nDecodes standard Base64 into a UTF-8 string."),
        "crypto.hex_encode" => Some("```conduit\nfunc crypto.hex_encode(data: String) -> String\n```\nEncodes UTF-8 string `data` as lowercase hexadecimal."),
        "crypto.hex_decode" => Some("```conduit\nfunc crypto.hex_decode(hex: String) -> String | CryptoError\n```\nDecodes hexadecimal into a UTF-8 string."),
        "crypto.uuid_v4" => Some("```conduit\nfunc crypto.uuid_v4() -> String\n```\nGenerates a random RFC 4122 UUID v4 string."),
        "crypto.random_bytes_hex" => Some("```conduit\nfunc crypto.random_bytes_hex(len: Int) -> String | CryptoError\n```\nGenerates `len` cryptographically random bytes encoded as hex."),
        "crypto.random_int" => Some("```conduit\nfunc crypto.random_int(min: Int, max: Int) -> Int | CryptoError\n```\nGenerates a random integer in `[min, max)`."),
        "json.decode" => Some("```conduit\nfunc json.decode<T>(raw: String) -> T | DecodeError\n```\nDecodes a strict RFC 8259 JSON string into typed struct/list/map `T`."),
        "json.encode" => Some("```conduit\nfunc json.encode<T>(value: T) -> String | EncodeError\n```\nSerializes `value` into a deterministic JSON string."),
        "json.parse" => Some("```conduit\nfunc json.parse(raw: String) -> json.Value | DecodeError\n```\nParses JSON into a dynamic `json.Value` tree."),
        "json.stringify" => Some("```conduit\nfunc json.stringify(val: json.Value) -> String | EncodeError\n```\nSerializes a dynamic `json.Value` into JSON text."),
        "time.now" => Some("```conduit\nfunc time.now() -> Timestamp | TimeError\n```\nReturns the current wall-clock UTC timestamp."),
        "time.monotonic" => Some("```conduit\nfunc time.monotonic() -> Instant\n```\nReturns a monotonic clock instant for elapsed duration measurement."),
        "time.elapsed" => Some("```conduit\nfunc time.elapsed(start: Instant) -> Duration | TimeError\n```\nReturns the elapsed `Duration` since `start`."),
        "time.seconds" => Some("```conduit\nfunc time.seconds(n: Int) -> Duration | TimeError\n```\nCreates a `Duration` of `n` seconds."),
        "time.milliseconds" => Some("```conduit\nfunc time.milliseconds(n: Int) -> Duration | TimeError\n```\nCreates a `Duration` of `n` milliseconds."),
        "validation.check" => Some("```conduit\nfunc validation.check<T>(value: T) -> T | ValidationError\n```\nValidates `value` against all `@validation.*` and custom `[#validator]` field rules."),
        _ => match word {
            "CliError" => Some("`struct CliError { kind: String, message: String }` (`cdt.cli`) — Returned on `--help` (`kind == \"help\"`) or CLI parse errors."),
            "EnvError" => Some("`struct EnvError { name: String, message: String }` (`cdt.env`) — Returned when a required env var is missing or invalid."),
            "ValidationError" => Some("`struct ValidationError { issues: [Issue] }` (`cdt.validation`) — Returned by `validation.check()` when one or more rules fail."),
            "Issue" => Some("`struct Issue { path: String, code: String, message: String }` (`cdt.validation`) — Single validation failure entry."),
            "DecodeError" => Some("`struct DecodeError { message: String }` (`cdt.json`) — Returned when JSON decoding fails."),
            "EncodeError" => Some("`struct EncodeError { message: String }` (`cdt.json`) — Returned when JSON encoding fails."),
            "TimeError" => Some("`struct TimeError { message: String }` (`cdt.time`) — Returned on invalid time/duration operations."),
            "Instant" => Some("Opaque monotonic clock measurement (`cdt.time`)."),
            "Timestamp" => Some("Opaque UTC wall-clock timestamp (`cdt.time`)."),
            "Duration" => Some("Opaque time span (`cdt.time`) with `.nanoseconds()`, `.milliseconds()`, `.seconds()`."),
            _ => None,
        },
    }
}

pub fn lookup_builtin_hover(word: &str) -> Option<&'static str> {
    match word {
        "export" => Some("**export** — Exposes a top-level `func`, `struct`, or `cli` declaration to importing modules."),
        "import" => Some("**import** — Imports symbols from a `cdt.*` module or relative `.cdt` file (`import { a } from \"./mod\"`)."),
        "func" => Some("**func** — Function declaration: `func name(param: Type) -> ReturnType { ... }`"),
        "struct" => Some("**struct** — Record type declaration: `struct Name { field: Type = default }`"),
        "cli" => Some("**cli** — Declarative CLI schema block (`flag`, `opt`, `arg`, `rest`, `cmd`, `group`)."),
        "group" => Some("**group** — Nested command group inside a `cli` block."),
        "cmd" => Some("**cmd** — Subcommand definition inside a `cli` or `group` block."),
        "flag" => Some("**flag** — Boolean CLI flag (`--name`, `-s`) inside a `cli` / `cmd` block."),
        "opt" => Some("**opt** — Named CLI option (`--name val`, `-s val`) inside a `cli` / `cmd` block."),
        "arg" => Some("**arg** — Positional CLI argument inside a `cli` / `cmd` block."),
        "rest" => Some("**rest** — Trailing positional `[String]` arguments inside a `cli` / `cmd` block."),
        "switch" => Some("**switch** — Exhaustive pattern matching over union/error/optional types."),
        "guard" => Some("**guard** — Early exit check: `guard cond else { return ... }`"),
        "print" => Some("`func print(value: Any) -> Void` — Prints a value to stdout."),
        "map" => Some("`list |> map((x: T) => U)` — Transforms each element of a list."),
        "filter" => Some("`list |> filter((x: T) => Bool)` — Keeps elements matching predicate."),
        "reduce" => Some("`func reduce<T, A>(list: [T], init: A, fn: (A, T) -> A) -> A` — Folds a list into a single value."),
        "len" => Some("`.len() -> Int` — Returns the length of a `String`, `[T]`, or `Map<K, V>`."),
        "split" => Some("`String.split(sep: String) -> [String]` — Splits a string by separator."),
        "write_lines" => Some("`Writer.write_lines(lines: [String]) -> Void | FsError` — Writes each string followed by `\\n` using the writer's buffer. An empty list writes nothing; call `.flush()` to check buffered I/O errors."),
        "contains" => Some("`.contains(item) -> Bool` — Checks whether substring or element is present."),
        "starts_with" => Some("`String.starts_with(prefix: String) -> Bool`"),
        "ends_with" => Some("`String.ends_with(suffix: String) -> Bool`"),
        "replace" => Some("`String.replace(from: String, to: String) -> String`"),
        "to_string" => Some("`.to_string() -> String` — Converts value to `String`."),
        "to_int" => Some("`String.to_int() -> Int | ParseError` — Parses a strict integer."),
        "to_float" => Some("`.to_float() -> Float | ParseError` (on `String`) or `Int.to_float() -> Float`."),
        "clamp" => Some("`.clamp(lo, hi)` — Clamps `Int` or `Float` to `[lo, hi]`."),
        "abs" => Some("`.abs()` — Returns absolute value of `Int` or `Float`."),
        _ => None,
    }
}

pub fn module_completions(alias: &str) -> Option<&'static str> {
    match alias {
        "cli" => Some(r#"[{"label":"parse","kind":3,"detail":"cli.parse<T>() -> T | CliError"},{"label":"parse_args","kind":3,"detail":"cli.parse_args<T>(args: [String]) -> T | CliError"},{"label":"help","kind":3,"detail":"cli.help<T>() -> String"},{"label":"CliError","kind":7,"detail":"struct CliError { kind: String, message: String }"}]"#),
        "env" => Some(r#"[{"label":"load","kind":3,"detail":"env.load<T>() -> T | EnvError"},{"label":"get","kind":3,"detail":"env.get(name: String) -> String?"},{"label":"require","kind":3,"detail":"env.require(name: String) -> String | EnvError"},{"label":"args","kind":3,"detail":"env.args() -> [String]"},{"label":"EnvError","kind":7,"detail":"struct EnvError { name: String, message: String }"}]"#),
        "fs" => Some(r#"[{"label":"read_text","kind":3,"detail":"fs.read_text(path: String) -> String | FsError"},{"label":"write_text","kind":3,"detail":"fs.write_text(path: String, data: String) -> Void | FsError"},{"label":"append_text","kind":3,"detail":"fs.append_text(path: String, data: String) -> Void | FsError"},{"label":"write_atomic","kind":3,"detail":"fs.write_atomic(path: String, data: String) -> Void | FsError"},{"label":"read_lines","kind":3,"detail":"fs.read_lines(path: String) -> [String] | FsError"},{"label":"each_line","kind":3,"detail":"fs.each_line(path: String, cb: (String) -> Void) -> Int | FsError"},{"label":"open_read","kind":3,"detail":"fs.open_read(path: String) -> Reader | FsError"},{"label":"open_write","kind":3,"detail":"fs.open_write(path: String) -> Writer | FsError"},{"label":"open_append","kind":3,"detail":"fs.open_append(path: String) -> Writer | FsError"},{"label":"exists","kind":3,"detail":"fs.exists(path: String) -> Bool"},{"label":"is_file","kind":3,"detail":"fs.is_file(path: String) -> Bool"},{"label":"is_dir","kind":3,"detail":"fs.is_dir(path: String) -> Bool"},{"label":"size","kind":3,"detail":"fs.size(path: String) -> Int | FsError"},{"label":"list_dir","kind":3,"detail":"fs.list_dir(path: String) -> [String] | FsError"},{"label":"mkdir_all","kind":3,"detail":"fs.mkdir_all(path: String) -> Void | FsError"},{"label":"remove","kind":3,"detail":"fs.remove(path: String) -> Void | FsError"},{"label":"copy","kind":3,"detail":"fs.copy(src: String, dst: String) -> Void | FsError"},{"label":"rename","kind":3,"detail":"fs.rename(src: String, dst: String) -> Void | FsError"},{"label":"FsError","kind":7,"detail":"struct FsError { kind: String, path: String, message: String }"},{"label":"Reader","kind":7,"detail":"streaming buffered file reader"},{"label":"Writer","kind":7,"detail":"streaming buffered file writer"}]"#),
        "path" => Some(r#"[{"label":"join","kind":3,"detail":"path.join(a: String, b: String) -> String"},{"label":"join_all","kind":3,"detail":"path.join_all(parts: [String]) -> String"},{"label":"dirname","kind":3,"detail":"path.dirname(p: String) -> String"},{"label":"basename","kind":3,"detail":"path.basename(p: String) -> String"},{"label":"ext","kind":3,"detail":"path.ext(p: String) -> String"},{"label":"stem","kind":3,"detail":"path.stem(p: String) -> String"},{"label":"normalize","kind":3,"detail":"path.normalize(p: String) -> String"},{"label":"is_abs","kind":3,"detail":"path.is_abs(p: String) -> Bool"},{"label":"with_ext","kind":3,"detail":"path.with_ext(p: String, ext: String) -> String"}]"#),
        "process" => Some(r#"[{"label":"run","kind":3,"detail":"process.run(cmd: String, args: [String]) -> Output | ProcessError"},{"label":"status","kind":3,"detail":"process.status(cmd: String, args: [String]) -> Int | ProcessError"},{"label":"cwd","kind":3,"detail":"process.cwd() -> String | ProcessError"},{"label":"set_cwd","kind":3,"detail":"process.set_cwd(dir: String) -> Void | ProcessError"},{"label":"pid","kind":3,"detail":"process.pid() -> Int"},{"label":"exit","kind":3,"detail":"process.exit(code: Int) -> Void"},{"label":"Output","kind":7,"detail":"struct Output { code: Int, stdout: String, stderr: String }"},{"label":"ProcessError","kind":7,"detail":"struct ProcessError { kind: String, message: String }"}]"#),
        "crypto" => Some(r#"[{"label":"sha256","kind":3,"detail":"crypto.sha256(data: String) -> String"},{"label":"hmac_sha256","kind":3,"detail":"crypto.hmac_sha256(key: String, data: String) -> String"},{"label":"base64_encode","kind":3,"detail":"crypto.base64_encode(data: String) -> String"},{"label":"base64_decode","kind":3,"detail":"crypto.base64_decode(b64: String) -> String | CryptoError"},{"label":"hex_encode","kind":3,"detail":"crypto.hex_encode(data: String) -> String"},{"label":"hex_decode","kind":3,"detail":"crypto.hex_decode(hex: String) -> String | CryptoError"},{"label":"uuid_v4","kind":3,"detail":"crypto.uuid_v4() -> String"},{"label":"random_bytes_hex","kind":3,"detail":"crypto.random_bytes_hex(len: Int) -> String | CryptoError"},{"label":"random_int","kind":3,"detail":"crypto.random_int(min: Int, max: Int) -> Int | CryptoError"},{"label":"CryptoError","kind":7,"detail":"struct CryptoError { kind: String, message: String }"}]"#),
        "json" => Some(r#"[{"label":"decode","kind":3,"detail":"json.decode<T>(raw: String) -> T | DecodeError"},{"label":"encode","kind":3,"detail":"json.encode<T>(val: T) -> String | EncodeError"},{"label":"parse","kind":3,"detail":"json.parse(raw: String) -> json.Value | DecodeError"},{"label":"stringify","kind":3,"detail":"json.stringify(val: json.Value) -> String | EncodeError"},{"label":"DecodeError","kind":7,"detail":"struct DecodeError"},{"label":"EncodeError","kind":7,"detail":"struct EncodeError"},{"label":"Value","kind":7,"detail":"json.Value"}]"#),
        "time" => Some(r#"[{"label":"now","kind":3,"detail":"time.now() -> Timestamp | TimeError"},{"label":"monotonic","kind":3,"detail":"time.monotonic() -> Instant"},{"label":"elapsed","kind":3,"detail":"time.elapsed(start: Instant) -> Duration | TimeError"},{"label":"seconds","kind":3,"detail":"time.seconds(n: Int) -> Duration | TimeError"},{"label":"milliseconds","kind":3,"detail":"time.milliseconds(n: Int) -> Duration | TimeError"},{"label":"Instant","kind":7,"detail":"time.Instant"},{"label":"Timestamp","kind":7,"detail":"time.Timestamp"},{"label":"Duration","kind":7,"detail":"time.Duration"},{"label":"TimeError","kind":7,"detail":"time.TimeError"}]"#),
        "validation" => Some(r#"[{"label":"check","kind":3,"detail":"validation.check<T>(val: T) -> T | ValidationError"},{"label":"min","kind":3,"detail":"@validation.min(n)"},{"label":"max","kind":3,"detail":"@validation.max(n)"},{"label":"email","kind":3,"detail":"@validation.email"},{"label":"ValidationError","kind":7,"detail":"struct ValidationError { issues: [Issue] }"},{"label":"Issue","kind":7,"detail":"struct Issue"}]"#),
        _ => None,
    }
}

